<?php
/** Member 2, Feature 4 - Lot-to-order traceability report. */
require_once __DIR__.'/../../includes/auth.php';require_role(['admin','production_manager']);
$pageTitle='Fabric Traceability';$currentNav='fabric_allocations';$lotId=filter_input(INPUT_GET,'lot_id',FILTER_VALIDATE_INT)?:0;$q=trim($_GET['q']??'');
$options=[];try{$res=$conn->query("SELECT fabric_lot_id,lot_number,fabric_type FROM fabric_lots ORDER BY fabric_lot_id DESC");if($res)$options=$res->fetch_all(MYSQLI_ASSOC);}catch(Throwable $e){error_log('Trace lot options failed: '.$e->getMessage());}
$lot=null;$inspections=[];$allocations=[];
if($lotId||$q!==''){
 try{
  if($lotId){$stmt=$conn->prepare("SELECT fl.*,s.supplier_name FROM fabric_lots fl JOIN suppliers s ON s.supplier_id=fl.supplier_id WHERE fl.fabric_lot_id=? LIMIT 1");$stmt->bind_param('i',$lotId);}else{$stmt=$conn->prepare("SELECT fl.*,s.supplier_name FROM fabric_lots fl JOIN suppliers s ON s.supplier_id=fl.supplier_id WHERE fl.lot_number=? LIMIT 1");$stmt->bind_param('s',$q);}
  $stmt->execute();$lot=$stmt->get_result()->fetch_assoc();$stmt->close();
  if($lot){$lotId=(int)$lot['fabric_lot_id'];$stmt=$conn->prepare("SELECT fi.*,u.full_name inspector_name,u.username inspector_username FROM fabric_inspections fi JOIN users u ON u.user_id=fi.inspector_id WHERE fi.fabric_lot_id=? ORDER BY fi.fabric_inspection_id DESC");$stmt->bind_param('i',$lotId);$stmt->execute();$inspections=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();$stmt=$conn->prepare("SELECT fa.*,pb.batch_number,pb.status batch_status,bo.order_number,bo.style_number,b.buyer_name,u.full_name allocator_name,u.username allocator_username FROM fabric_allocations fa JOIN production_batches pb ON pb.batch_id=fa.batch_id JOIN buyer_orders bo ON bo.order_id=pb.order_id JOIN buyers b ON b.buyer_id=bo.buyer_id JOIN users u ON u.user_id=fa.allocated_by WHERE fa.fabric_lot_id=? ORDER BY fa.fabric_allocation_id DESC");$stmt->bind_param('i',$lotId);$stmt->execute();$allocations=$stmt->get_result()->fetch_all(MYSQLI_ASSOC);$stmt->close();}
 }catch(Throwable $e){error_log('Fabric trace failed: '.$e->getMessage());flash_set('error','Traceability data could not be loaded. Ensure both Member 2 schema files are installed.');}
}
$allocated=0.0;foreach($allocations as $a)$allocated+=(float)$a['allocated_quantity'];$available=$lot?(float)$lot['received_quantity']-$allocated:0;
include __DIR__.'/../../includes/header.php';include __DIR__.'/../../includes/sidebar.php';
?>
<div class="page-header"><div class="page-title-group"><h1>Fabric Lot Traceability</h1><div class="page-subtitle">Follow one lot from supplier receipt through inspection to buyer order and production batch</div></div><div class="page-actions"><a class="btn btn-secondary" href="<?=e(url('modules/fabric_allocations/index.php'))?>">Allocation History</a></div></div>
<div class="card mb-4"><div class="card-body"><form method="get" class="filter-bar"><div class="filter-field-grow"><label class="form-label" for="lot_id">Select Fabric Lot</label><select class="form-control" id="lot_id" name="lot_id"><option value="">-- Select Lot --</option><?php foreach($options as $o):?><option value="<?=(int)$o['fabric_lot_id']?>" <?=$lotId===(int)$o['fabric_lot_id']?'selected':''?>><?=e($o['lot_number'].' — '.$o['fabric_type'])?></option><?php endforeach?></select></div><div class="filter-field-grow"><label class="form-label" for="q">Or enter exact lot number</label><input class="form-control" id="q" name="q" value="<?=e($q)?>" placeholder="LOT-TEST-001"></div><div class="filter-actions"><button class="btn btn-primary">Trace Lot</button></div></form></div></div>
<?php if(($lotId||$q!=='')&&!$lot):?><div class="alert alert-warning">No fabric lot matched your selection.</div><?php endif?>
<?php if($lot):?>
<div class="card mb-4"><div class="card-header"><h2>1. Supplier &amp; Receiving</h2><span class="badge badge-info"><?=e($lot['inspection_status'])?></span></div><div class="card-body"><table class="details-table"><tr><th>Lot</th><td><?=e($lot['lot_number'])?></td></tr><tr><th>Supplier</th><td><?=e($lot['supplier_name'])?></td></tr><tr><th>Fabric</th><td><?=e($lot['fabric_type'])?><?= $lot['color']?' — '.e($lot['color']):''?></td></tr><tr><th>Received</th><td><?=number_format((float)$lot['received_quantity'],2)?> <?=e($lot['unit'])?> on <?=e(date('M d, Y',strtotime($lot['received_date'])))?></td></tr><tr><th>Allocated / Available</th><td><?=number_format($allocated,2)?> / <?=number_format($available,2)?> <?=e($lot['unit'])?></td></tr></table></div></div>
<div class="card mb-4"><div class="card-header"><h2>2. Fabric Inspection History</h2><span class="badge badge-muted"><?=count($inspections)?> Record(s)</span></div><div class="card-body" style="padding:0"><?php if(!$inspections):?><div class="empty-state"><p>This lot has not been inspected.</p><a class="btn btn-primary btn-sm" href="<?=e(url('modules/fabric_inspections/create.php?lot_id='.$lotId))?>">Record Inspection</a></div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Date</th><th>Quantity</th><th>Points</th><th>Result</th><th>Inspector</th><th>Action</th></tr></thead><tbody><?php foreach($inspections as $i):?><tr><td><?=e(date('M d, Y',strtotime($i['inspection_date'])))?></td><td><?=number_format((float)$i['inspected_quantity'],2)?> <?=e($lot['unit'])?></td><td><?=(int)$i['penalty_points']?></td><td><?=e($i['result'])?></td><td><?=e($i['inspector_name']?:$i['inspector_username'])?></td><td><a class="btn btn-sm btn-secondary" href="<?=e(url('modules/fabric_inspections/view.php?id='.(int)$i['fabric_inspection_id']))?>">View</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></div></div>
<div class="card"><div class="card-header"><h2>3. Production Batch &amp; Buyer Order Links</h2><span class="badge badge-muted"><?=count($allocations)?> Allocation(s)</span></div><div class="card-body" style="padding:0"><?php if(!$allocations):?><div class="empty-state"><p>This lot has not been allocated.</p><?php if(in_array($lot['inspection_status'],['Passed','Conditionally Approved'],true)):?><a class="btn btn-primary btn-sm" href="<?=e(url('modules/fabric_allocations/create.php?lot_id='.$lotId))?>">Allocate Fabric</a><?php endif?></div><?php else:?><div class="table-responsive"><table class="table"><thead><tr><th>Batch</th><th>Order</th><th>Style / Buyer</th><th>Quantity</th><th>Date</th><th>Action</th></tr></thead><tbody><?php foreach($allocations as $a):?><tr><td><strong><?=e($a['batch_number'])?></strong><div class="text-xs text-muted"><?=e($a['batch_status'])?></div></td><td><?=e($a['order_number'])?></td><td><?=e($a['style_number'])?><div class="text-xs text-muted"><?=e($a['buyer_name'])?></div></td><td><?=number_format((float)$a['allocated_quantity'],2)?> <?=e($lot['unit'])?></td><td><?=e(date('M d, Y',strtotime($a['allocated_date'])))?></td><td><a class="btn btn-sm btn-secondary" href="<?=e(url('modules/fabric_allocations/view.php?id='.(int)$a['fabric_allocation_id']))?>">View</a></td></tr><?php endforeach?></tbody></table></div><?php endif?></div></div>
<?php endif?>
<?php echo '<link rel="stylesheet" href="modern-ui.css">'; include __DIR__.'/../../includes/footer.php';
